import React from 'react';
import { StyleSheet, View, Text, TouchableOpacity } from 'react-native';
import { Ionicons } from '@expo/vector-icons';

const Calendar = ({ selectedDate, onDateSelect, currentMonth, onMonthChange }) => {
  const daysOfWeek = ['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CB'];
  
  // Sample calendar data for April
  const calendarData = [
    // Week 1 (previous month dates)
    [26, 27, 28, 29, 30, 31, 1],
    // Week 2
    [2, 3, 4, 5, 6, 7, 8],
    // Week 3
    [9, 10, 11, 12, 13, 14, 15],
    // Week 4
    [16, 17, 18, 19, 20, 21, 22],
    // Week 5
    [23, 24, 25, 26, 27, 28, 29],
    // Week 6 (next month dates)
    [30, 1, 2, 3, 4, 5, 6]
  ];

  const getDateIndicators = (date) => {
    // Dates with multiple indicators (1-8)
    if (date >= 1 && date <= 8) {
      return ['#FF6B35', '#FFD23F', '#8B5CF6', '#20B2AA'];
    }
    // Dates with single indicator (9-23, except 24)
    if ((date >= 9 && date <= 23) || (date >= 25 && date <= 29)) {
      return ['#20B2AA'];
    }
    // Date 24 has single indicator
    if (date === 24) {
      return ['#20B2AA'];
    }
    return [];
  };

  const renderDateCell = (date, isCurrentMonth = true) => {
    const indicators = getDateIndicators(date);
    const isSelected = selectedDate === date;
    const isCurrentDate = date === 6; // Current date is 6th

    return (
      <TouchableOpacity
        key={date}
        style={styles.dateCell}
        onPress={() => onDateSelect(date)}
      >
        {isCurrentDate ? (
          <View style={styles.currentDateCircle}>
            <Text style={styles.currentDateText}>{date}</Text>
          </View>
        ) : isSelected ? (
          <View style={styles.selectedDateCircle}>
            <Text style={styles.selectedDateText}>{date}</Text>
          </View>
        ) : (
          <Text style={[
            styles.dateText,
            !isCurrentMonth && styles.otherMonthDateText
          ]}>
            {date}
          </Text>
        )}
        
        {indicators.length > 0 && (
          <View style={styles.indicatorsContainer}>
            {indicators.map((color, index) => (
              <View
                key={index}
                style={[styles.indicator, { backgroundColor: color }]}
              />
            ))}
          </View>
        )}
      </TouchableOpacity>
    );
  };

  return (
    <View style={styles.container}>
      {/* Days of Week */}
      <View style={styles.daysOfWeek}>
        {daysOfWeek.map((day, index) => (
          <Text key={index} style={styles.dayOfWeekText}>{day}</Text>
        ))}
      </View>

      {/* Calendar Grid */}
      <View style={styles.calendarGrid}>
        {calendarData.map((week, weekIndex) => (
          <View key={weekIndex} style={styles.weekRow}>
            {week.map((date, dayIndex) => {
              const isCurrentMonth = (weekIndex === 0 && date > 20) || 
                                   (weekIndex > 0 && weekIndex < 5) || 
                                   (weekIndex === 5 && date < 10);
              return renderDateCell(date, isCurrentMonth);
            })}
          </View>
        ))}
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    backgroundColor: '#ffffff',
    paddingHorizontal: 20,
    paddingVertical: 20,
  },
  daysOfWeek: {
    flexDirection: 'row',
    justifyContent: 'space-around',
    marginBottom: 10,
  },
  dayOfWeekText: {
    fontSize: 14,
    fontWeight: '500',
    color: '#666666',
    width: 40,
    textAlign: 'center',
  },
  calendarGrid: {
    flexDirection: 'column',
  },
  weekRow: {
    flexDirection: 'row',
    justifyContent: 'space-around',
    marginBottom: 8,
  },
  dateCell: {
    width: 40,
    height: 50,
    justifyContent: 'center',
    alignItems: 'center',
    position: 'relative',
  },
  dateText: {
    fontSize: 16,
    fontWeight: '500',
    color: '#333333',
  },
  otherMonthDateText: {
    color: '#CCCCCC',
  },
  currentDateCircle: {
    width: 32,
    height: 32,
    borderRadius: 16,
    backgroundColor: '#20B2AA',
    justifyContent: 'center',
    alignItems: 'center',
  },
  currentDateText: {
    fontSize: 16,
    fontWeight: 'bold',
    color: '#ffffff',
  },
  selectedDateCircle: {
    width: 32,
    height: 32,
    borderRadius: 16,
    backgroundColor: '#F0F0F0',
    borderWidth: 2,
    borderColor: '#CCCCCC',
    justifyContent: 'center',
    alignItems: 'center',
  },
  selectedDateText: {
    fontSize: 16,
    fontWeight: 'bold',
    color: '#333333',
  },
  indicatorsContainer: {
    flexDirection: 'row',
    justifyContent: 'center',
    marginTop: 2,
    flexWrap: 'wrap',
  },
  indicator: {
    width: 4,
    height: 4,
    borderRadius: 2,
    marginHorizontal: 1,
  },
});

export default Calendar;
